1	#!/usr/bin/env bun
2	/**
3	 * dispatch_pr_validation.ts — hand a pull request to validation, from a workflow step.
4	 *
5	 * ## Why a person's command goes through validation rather than straight to the agent
6	 *
7	 * A person commenting `/<agent>` on a pull request is asking for a run, and the run
8	 * they are asking for is a judgement about a commit. Starting it immediately means
9	 * it reads a CI result that does not exist yet -- so it either waits with nothing
10	 * able to wake it, or reviews a commit whose checks have not run. Validation is the
11	 * thing that runs CI and waits, and it already dispatches whoever the result calls
12	 * for.
13	 *
14	 * So every agent start on a pull request goes through it, whoever asked: an agent's
15	 * handoff, a person's comment, and the re-validation after a push. One path, one
16	 * place that knows how to wait.
17	 *
18	 * ## What `asked-by-person` changes
19	 *
20	 * Who a FAILED check goes back to. An agent that broke its own pull request fixes
21	 * it; a person who asked for a run is owed the answer themselves, and handing their
22	 * request to an agent would be the machinery deciding on their behalf. See
23	 * `ValidationInput.askedByPerson`.
24	 *
25	 * Usage:
26	 *   dispatch_pr_validation.ts --repo OWNER/REPO --number N --branch B [--asked-by-person]
27	 */
28	import { parseArgs } from "node:util";
29	import { dispatchPrValidation } from "../../adapters/actions/dispatch-targets.ts";
30	import { isTrue } from "./lib/flags.ts";
31	import { defineScript } from "./lib/script-ref.ts";
32	
33	export interface DispatchPrValidationArgs {
34	  repo: string;
35	  number: string | number;
36	  branch: string;
37	  "asked-by-person"?: string;
38	}
39	
40	export const ref = defineScript<DispatchPrValidationArgs>(import.meta.url);
41	
42	function main(): void {
43	  const { values } = parseArgs({
44	    args: Bun.argv.slice(2),
45	    options: {
46	      repo: { type: "string" },
47	      number: { type: "string" },
48	      branch: { type: "string" },
49	      "asked-by-person": { type: "string" },
50	    },
51	  });
52	
53	  const repo = values.repo ?? "";
54	  const number = values.number ?? "";
55	  const branch = values.branch ?? "";
56	  if (!repo || !number || !branch) {
57	    console.error("usage: dispatch_pr_validation.ts --repo OWNER/REPO --number N --branch B");
58	    process.exit(2);
59	  }
60	
61	  // `dispatchPrValidation` reads the agent names from the pull request itself, so
62	  // there is nothing to pass but the target. `asked-by-person` travels as a
63	  // workflow input because it is a fact about THIS request rather than about the
64	  // pull request -- the same pull request can be validated by an agent's push and
65	  // by a person's comment, and the two route a failure differently.
66	  const dispatched = dispatchPrValidation(repo, Number(number), branch, {
67	    askedByPerson: isTrue(values["asked-by-person"]),
